const AM=[{k:'pf',t:'กำไร-ขาดทุน',f:pfOf,x:fmtB,dir:1},{k:'ratio',t:'ค่าใช้จ่ายต่อรายได้',f:M_.ratio,x:v=>fmtP(v),dir:-1},{k:'util',t:'อัตราการใช้งาน',f:M_.util,x:v=>fmtP(v),dir:1},{k:'fr',t:'น้ำมันต่อรายได้',f:M_.fr,x:v=>fmtP(v),dir:-1},{k:'kl',t:'กม./ลิตร',f:M_.kl,x:v=>fmtN(v,2),dir:1},{k:'bk',t:'บาท/กม.',f:M_.bk,x:v=>fmtN(v,2),dir:-1},{k:'pcars',t:'รถทำกำไร (ภาค/DC)',f:M_.pcars,x:v=>fmtP(v),dir:1}];
function issues(o){const t=[];if(M_.util(o)<75)t.push('ใช้งานต่ำ');if(M_.ratio(o)>130)t.push('ต้นทุนสูง');if(pfOf(o)<0)t.push('ขาดทุน');if(!o.km)t.push('ไม่มีเที่ยววิ่ง');return t}
function analysisRows(){const k=AM.find(x=>x.k===S.ametric)||AM[0],kind=S.adim;let R=dim(kind).filter(o=>kind!=='car'||o.car);if(k.k==='pcars'&&kind==='car'){return{k:AM[0],R:R.sort((a,b)=>pfOf(a)-pfOf(b))}}R=R.filter(o=>Number.isFinite(k.f(o)));R.sort((a,b)=>(k.f(a)-k.f(b))*k.dir);return{k,R}}
VIEW.analysis=()=>{const{k,R}=analysisRows(),P=pal(),w=W(),top=R.slice(0,Math.min(R.length,15));const n=R.filter(o=>issues(o).length).length;
 return`${header('ผลการวิเคราะห์',esc(scope())+` · เรียงจากแย่ไปดีตาม ${esc(k.t)} · พบปัญหา ${n} จาก ${R.length} รายการ`)}
 <section class="card"><div class="tools" style="justify-content:center"><div class="seg2">${[['zone','ภาค'],['dc','DC'],['car','ทะเบียน']].map(([d,t])=>`<button data-act="adim:${d}" aria-pressed="${S.adim===d}">${t}</button>`).join('')}</div><select id="f-am" aria-label="เรียงตาม">${AM.filter(a=>S.adim!=='car'||a.k!=='pcars').map(a=>`<option value="${a.k}"${S.ametric===a.k?' selected':''}>${a.t}</option>`).join('')}</select></div>
 <h2>${top.length} อันดับแรกที่แย่ที่สุด</h2><p class="note">กดแถบเพื่อเจาะลึก</p><div class="chart">${hbars({items:top.map(o=>({l:S.adim==='car'?o.name:zl(o),v:k.f(o),act:dimAct(S.adim,o),c:P.bad})),P,W:Math.min(w,760),fmt:k.x,labelW:S.adim==='dc'?190:136})}</div></section>
 <section class="card"><h2>ผลทุกมิติ</h2><p class="note">แสดงผลโดยไม่ให้เกรด</p>${table('an',[{k:'rank',t:'#',v:o=>R.indexOf(o)+1},colName(S.adim==='car'?'ทะเบียน':S.adim==='dc'?'DC':'ภาค',o=>o.name),...(S.adim==='car'?LOC:[CN]),{k:'iss',t:'ประเด็น',v:o=>issues(o).length,html:o=>issues(o).map(t=>`<span class="tag">${t}</span>`).join('')||'–'},...NUMCOLS.slice(0,6),{k:'kl',t:'กม./ลิตร',v:M_.kl,txt:o=>fmtN(M_.kl(o),2),heat:1},NUMCOLS[8]],R,{act:o=>dimAct(S.adim,o),search:'ค้นหา',tot:S.adim==='zone'?zoneTot(filt()):null,fit:S.adim==='zone'})}</section>`};
VIEW.check=()=>{const m=months[S.mode==='month'?S.mi:cal[range()[1]].mi];const s=DATA.summary[m]||{dup:0,rev:0,fuel:0,fuelraw:0};const A=DATA.adj.filter(a=>a.m===m&&carBy[a.pl]&&(!S.adjK||a.k===S.adjK));const c={};DATA.adj.filter(a=>a.m===m).forEach(a=>c[a.k]=(c[a.k]||0)+1);const add=s.fuel-s.fuelraw;
 return`${header('ตรวจสอบข้อมูล',mLabel(m)+' · รายการที่ระบบปรับตามกติกา เพื่อใช้ตามแก้ที่ต้นทาง')}<div class="stats"><div class="stat"><span>แถวไมล์ที่ปรับ</span><b>${fmtN(c['ไมล์']||0)}</b></div><div class="stat"><span>วันที่ปรับค่าน้ำมัน</span><b>${fmtN(c['น้ำมัน']||0)}</b><em>เพิ่ม ${fmtN(add)} บาท</em></div><div class="stat"><span>ตัดน้ำมันเบิ้ล</span><b>${fmtN(s.dup)}</b><em>บาท</em></div><div class="stat"><span>รายได้ที่นำมาคำนวณ</span><b>${fmtN(s.rev)}</b><em>บาท</em></div></div>
 <section class="card"><h2>กติกาที่ใช้คำนวณ</h2><ul class="say" style="margin:6px 0 0;padding-left:20px;max-width:none"><li>รถบริษัทรหัส 01 ชนิด 040 และ 042 ตามฐานรถปัจจุบัน ไม่นับรถที่ขายแล้ว และไม่นับ DC 690</li><li>รายได้ = รถขนย้าย + รถกระจาย + ค่าเข้ารับ</li><li>ไมล์ต่อเที่ยวเกิน 1,000 กม. หรือไม่เกิน 0 ถือว่าผิด ใช้ระยะทางจากรายงานน้ำมันถ้าถูกต้อง ไม่เช่นนั้นใช้ค่าเฉลี่ยของทะเบียน</li><li>ค่าน้ำมันใช้ค่าสูงสุดต่อทะเบียนต่อวัน วันที่ต่ำกว่า 100 บาทถือว่าผิด ใช้บาท/กม. เฉลี่ยของทะเบียน × ระยะทาง</li><li>ค่าเช่าคิดตามวันทำการในปฏิทิน สูงสุด ${CAP} วัน</li><li>ค่าซ่อม 040 = 1.00 บาท/กม. และ 042 = 1.50 บาท/กม.</li><li>ค่าใช้จ่าย = ค่าเช่า + น้ำมัน + ค่าจ้าง + Incentive + ค่าซ่อม</li></ul></section>
 <section class="card"><h2>รายการที่ปรับ ${A.length} รายการ</h2><div class="tools" style="justify-content:center"><div class="seg2">${[['','ทั้งหมด'],['ไมล์','ไมล์'],['น้ำมัน','น้ำมัน']].map(([k,t])=>`<button data-act="adjk:${k}" aria-pressed="${S.adjK===k}">${t}</button>`).join('')}</div></div>${table('adj',[{k:'pl',t:'ทะเบียน',v:a=>a.pl},{k:'zn',t:'ภาค',v:a=>carLoc(carBy[a.pl]).z},{k:'dn',t:'DC',v:a=>carLoc(carBy[a.pl]).d},{k:'d',t:'วันที่',v:a=>a.d},{k:'k',t:'รายการ',v:a=>a.k},{k:'old',t:'ค่าเดิม',v:a=>a.old,txt:a=>fmtN(a.old,2)},{k:'new',t:'ค่าที่ใช้',v:a=>a.new,txt:a=>fmtN(a.new,2)},{k:'why',t:'วิธีปรับ',v:a=>a.why}],A,{act:a=>'car:'+a.pl,search:'ค้นหาทะเบียน'})}</section>`};
/* ---------- render + events ---------- */
function render(keepScroll){if(!VIEW[S.page]||(!window.ADMIN&&(S.page==='check'||S.page==='settings')))S.page='home';renderShell();const y=window.scrollY;$('#view').innerHTML=VIEW[S.page]();window.scrollTo(0,keepScroll?y:0);try{localStorage.setItem('fleet-ui',JSON.stringify({group:S.group}))}catch(e){}}
function carSheet(pl){const c=carBy[pl],r=range(),R=rows.filter(x=>x.pl===pl&&x.i>=r[0]&&x.i<=r[1]),o=calc(r,{plate:pl},null).get('all')||blank();const A=(DATA.adj||[]).filter(a=>a.pl===pl);const keyd=(a)=>a.d;const adjSet=new Set(A.map(a=>{const [d,mm,y]=a.d.split('/');return y+'-'+mm+'-'+(+d)}));
 openSheet(`<h2>${esc(pl)}</h2><p class="say" style="margin:0">ภาค ${esc(carLoc(c).z)} · ${esc(carLoc(c).d)}${carDc(c)!==c.dc?' (DC ฐาน '+esc(dcName(c.dc))+')':''}<br>${c.g==='A'?'รถใช้งาน':'รถ Stock'} · ${c.ty} · ปี ${c.yr} · ค่าเช่า ${c.rate} บาท/วัน</p><div class="stats"><div class="stat"><span>รายได้</span><b>${fmtN(o.rev)}</b></div><div class="stat"><span>ค่าใช้จ่าย</span><b>${fmtN(rowCost(o))}</b></div><div class="stat"><span>กำไร-ขาดทุน</span><b>${fmtB(pfOf(o))}</b></div><div class="stat"><span>กม./ลิตร</span><b>${fmtN(M_.kl(o),2)}</b></div></div>
 <div class="tw"><table class="t"><thead><tr><th>วัน</th><th>ภาค</th><th>DC</th><th>กม.</th><th>รายได้</th><th>น้ำมัน</th></tr></thead><tbody>${R.map(x=>`<tr><td>${TD[x.c.dow]} ${x.c.label}${adjSet.has(x.c.m+'-'+x.c.d)?' *':''}</td><td>${esc(zoneOf(x.dc))}</td><td>${esc(dcName(x.dc))}</td><td>${fmtN(x.km)}</td><td>${fmtN(x.rev)}</td><td>${fmtN(x.fuel)}</td></tr>`).join('')||'<tr><td colspan="6">ไม่มีเที่ยววิ่งในช่วงที่เลือก</td></tr>'}</tbody></table></div><p class="note">* วันที่มีการปรับข้อมูล</p>`)}
function openSheet(html){const o=$('#ov');o.hidden=false;$('#sheet').innerHTML=`<button class="close" data-act="close" aria-label="ปิด">✕</button>${html}`}
function closeSheet(){$('#ov').hidden=true}
document.addEventListener('click',e=>{const t=e.target.closest('[data-act]');if(!t){return}const [a,...rest]=t.dataset.act.split(':'),v=rest.join(':');
 if(a==='close'){closeSheet();return}
 if(a==='car'){carSheet(v);return}
 if(a==='export'){openExport();return}
 if(a==='theme'){const r=document.documentElement,c=r.getAttribute('data-theme')||(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'),n=c==='dark'?'light':'dark';r.setAttribute('data-theme',n);try{localStorage.setItem('fleet-theme',n)}catch(x){}render(true);return}
 if(a.startsWith('do')){if(window.doExport)window.doExport(a);return}
 if(a==='page'){S.page=v;render();return}
 if(a==='sort'){const[id,k]=[rest[0],rest[1]],s=S.sort[id];S.sort[id]={k,d:s&&s.k===k?-s.d:1};render(true);return}
 if(a==='group'){S.group=v}else if(a==='mode'){S.mode=v;if(v==='day'&&S.day===cal.length-1)S.day=[...cal.keys()].filter(i=>cal[i].wd).pop()}else if(a==='zone'){const off=v&&S.zone===v&&S.page!=='analysis';S.zone=off?'':v;S.dc='';if(v&&S.page==='analysis')S.adim='dc';if(S.zone)goDetail=true}else if(a==='dc'){const off=v&&String(S.dc)===v&&S.page!=='analysis';S.dc=off?'':v;if(S.dc)S.zone=zoneOf(+S.dc);if(v&&S.page==='analysis')S.adim='car'}else if(a==='type'){S.type=v}else if(a==='day'){S.mode='day';S.day=+v}else if(a==='adim'){S.adim=v}else if(a==='adjk'){S.adjK=v}else return;
 render(true);if(goDetail){goDetail=false;const d=$('#zone-detail');if(d)d.scrollIntoView({block:'start'})}});
