const GE={A:'🔵',B:'🟦',C:'🟡',D:'🟠',F:'🔴'},KE={pf:'💰',ratio:'💸',util:'📅',pcars:'🏆',klAB:'⛽',klCC:'❄️',bkAB:'🛻',bkCC:'🚚'},CE={'ค่าเช่า':'🚛','น้ำมัน':'⛽','ค่าจ้าง':'👷','ค่าซ่อม':'🔧','Incentive':'🎁'},MD=['1️⃣','2️⃣','3️⃣','4️⃣','5️⃣'];
function summaryText(){const K=kpiData(),L=['📊 NIMEX Car Performance Dashboard',`🗓️ ${rangeLabel()}  |  🚚 ${groupLabel()}${S.dc?'  |  📍 '+dcName(+S.dc):S.zone?'  |  📍 ภาค '+S.zone:''}`];
 const sec=t=>{L.push('');L.push(t)};
 if(picked.has('kpi')){sec('🎯 ผลสำคัญ');K.list.forEach(k=>{if(k.id==='pf'&&!k.show)return;const tr=k.up===null?'':k.up?' ✅':' ⚠️';L.push(`${KE[k.id]} ${k.l}: ${k.txt}${k.unit?' '+k.unit:''}${k.show&&k.g?' '+GE[k.g]+' เกรด '+k.g:''}`);if(K.q)L.push(`     ก่อนหน้า ${k.prev}${tr}`)});L.push(`💵 รายได้: ${fmtN(K.o.rev)} บาท`);L.push(`🛣️ ระยะทาง: ${fmtN(K.o.km)} กม.`);L.push(`🛢️ น้ำมันต่อรายได้: ${fmtP(M_.fr(K.o))}`)}
 if(picked.has('cost')){sec(`🧾 ค่าใช้จ่ายรวม ${fmtN(rowCost(K.o))} บาท`);costParts(K.o,LIGHT).forEach(p=>L.push(`${CE[p.l]} ${p.l}: ${fmtN(p.v)} บาท (${fmtP(p.v/rowCost(K.o)*100,0)})`))}
 if(picked.has('zone')){sec('🗺️ ภาคที่ขาดทุนสูงสุด');dim('zone').sort((a,b)=>pfOf(a)-pfOf(b)).slice(0,3).forEach((z,i)=>L.push(`${MD[i]} ${z.name} (${fmtN(z.carsN)} คัน): ${fmtM(pfOf(z))} ล้านบาท`))}
 if(picked.has('cmp')){const{c,ms,rows:R}=cmpRows(),n=ms.length;if(n>1){sec(`🔁 เทียบรายเดือน: ${c.t}`);R.map(r=>({r,d:r.vals[n-1]-r.vals[n-2]})).filter(x=>Number.isFinite(x.d)).sort((a,b)=>(a.d-b.d)*(c.hi?1:-1)).slice(0,3).forEach(x=>{const g=c.hi?x.d>=0:x.d<=0;L.push(`${g?'📈':'📉'} ${x.r.name}: ${c.x(x.r.vals[n-1])} (${x.d>=0?'▲':'▼'} ${c.x(Math.abs(x.d))})`)})}}
 if(picked.has('worst')){sec('🚨 รถที่ขาดทุนสูงสุด');dim('car').sort((a,b)=>pfOf(a)-pfOf(b)).slice(0,5).forEach((c,i)=>{const x=carLoc(c);L.push(`${MD[i]} ${c.name} (${x.z} / ${x.d}): ${fmtB(pfOf(c))} บาท`)})}
 if(picked.has('analysis')){const{k:m,R}=analysisRows();sec(`🔎 ผลการวิเคราะห์: แย่สุดตาม ${m.t}`);R.slice(0,3).forEach((o,i)=>L.push(`${MD[i]} ${o.name}: ${m.x(m.f(o))}`))}
 return L.join('\n')}
