async function diag(){if(!window.claude||!claude.use)return'no-runtime';let s='?';try{const p=await claude.use('permissions');s=p?await p.state('downloads'):'no-permissions'}catch(x){s='err'}return'dl-null/'+s}
async function fallback(filename,data){const box=$('#xfall');if(!box)return;const ext=filename.split('.').pop(),code=await diag();
 if(ext==='png'){const u=await blob64(data instanceof Blob?data:new Blob([data]));box.innerHTML=`<p class="msg">หน้าจอนี้บันทึกไฟล์โดยตรงไม่ได้ กดค้างหรือคลิกขวาที่รูปเพื่อบันทึกภาพ (${esc(code)})</p><img src="${u}" alt="ภาพสรุปผล" style="width:100%;border:1px solid var(--line);border-radius:10px">`;say('สร้างรูปแล้ว ดูด้านล่าง');return}
 if(ext==='xlsx'){const tsv=sheetsData().map(([n,d])=>n+'\n'+d.map(r=>r.join('\t')).join('\n')).join('\n\n');box.innerHTML=`<p class="msg">หน้าจอนี้บันทึกไฟล์โดยตรงไม่ได้ คัดลอกตารางด้านล่างไปวางใน Excel ได้เลย (${esc(code)})</p><textarea id="tsv-text" aria-label="ตารางสำหรับวางใน Excel">${esc(tsv)}</textarea><button class="btn alt" data-act="docopytsv">คัดลอกตาราง</button>`;say('เตรียมตารางแล้ว ดูด้านล่าง');return}
 box.innerHTML=`<p class="msg">หน้าจอนี้สร้างไฟล์ PowerPoint ให้ดาวน์โหลดไม่ได้ ใช้รูปภาพ PNG แทน หรือเปิด Dashboard จากเว็บ claude.ai (${esc(code)})</p>`;say('')}
async function save(filename,data){if(window.__testSave)return window.__testSave(filename,data);if(window.__STANDALONE){const f=new File([data],filename,{type:'application/octet-stream'}),u=await blob64(f),a=document.createElement('a');a.href=u;a.download=filename;document.body.appendChild(a);a.click();a.remove();say('ดาวน์โหลดไฟล์แล้ว');return}if(!dl)try{if(window.claude&&claude.use)dl=await claude.use('downloads')}catch(e){}if(!dl){await fallback(filename,data);return}
 try{await dl.save({filename,data});say('บันทึกไฟล์แล้ว')}catch(e){if(e&&e.code==='declined')say('ยกเลิกการบันทึกแล้ว');else if(e&&e.code==='rate_limited')say('มีหน้าต่างบันทึกเปิดอยู่ รอสักครู่แล้วลองใหม่');else{say('');await fallback(filename,data instanceof ArrayBuffer&&!data.byteLength?new Blob([]):data)}}}
/* section -> {title, svg body, h} drawn on a fixed 1200 canvas with light colours */
function svgTable(cols,data,W){const rh=30,cw=W/cols.length,c0=cols.length>5?Math.max(cw*1.5,190):cw*1.4,cr=(W-c0)/(cols.length-1);const xs=i=>i===0?0:c0+(i-1)*cr;let s=`<rect width="${W}" height="${rh+2}" rx="7" fill="#0a2a5e"/>`;cols.forEach((c,i)=>{s+=`<text x="${i?xs(i)+cr-8:10}" y="21" text-anchor="${i?'end':'start'}" font-size="14" font-weight="600" fill="#fff">${esc(c.t)}</text>`});
 data.forEach((r,j)=>{const y=(j+1)*rh+2;if(j%2)s+=`<rect y="${y}" width="${W}" height="${rh}" fill="#f2f5fb"/>`;cols.forEach((c,i)=>{s+=`<text x="${i?xs(i)+cr-8:10}" y="${y+20}" text-anchor="${i?'end':'start'}" font-size="14" font-weight="${i?400:600}" fill="#0b1f3f">${esc(c.txt?c.txt(r):c.v(r))}</text>`})});return{s,h:(data.length+1)*rh+4}}
function embed(svg,x,y,w){const m=svg.match(/viewBox="0 0 ([\d.]+) ([\d.]+)"/),sc=w/+m[1],inner=svg.replace(/^<svg[^>]*>/,'').replace(/<\/svg>$/,'').replace(/ data-(tip|act)="[^"]*"/g,'');return{s:`<g transform="translate(${x} ${y}) scale(${sc})">${inner}</g>`,h:+m[2]*sc}}
function secDraw(k,W=1200){const P=LIGHT,K=kpiData();
 if(k==='kpi'){const cw=(W-3*14)/4,ch=130;let s='';K.list.forEach((t,i)=>{const x=i%4*(cw+14),y=Math.floor(i/4)*(ch+14),g=t.show?t.g:null,bar={A:'#123f8c',B:'#6e93d6',C:'#d4a72c',D:'#d9822b',F:'#b8334a'}[g]||'#d4af37';
   s+=`<g transform="translate(${x} ${y})"><rect width="${cw}" height="${ch}" rx="14" fill="#0a2a5e"/><rect y="${ch-5}" width="${cw}" height="5" fill="${bar}"/><text x="${cw/2}" y="30" text-anchor="middle" font-size="16" fill="#d9c98a">${esc(t.l)}</text><text x="${cw/2}" y="76" text-anchor="middle" font-size="34" font-weight="600" font-family="Prompt,sans-serif" fill="#fff">${esc(t.txt)}</text><text x="${cw/2}" y="104" text-anchor="middle" font-size="14" fill="#cfdcf2">${esc(t.unit)}${K.q?' · ก่อนหน้า '+esc(t.prev):''}</text>${g?`<rect x="${cw-40}" y="10" width="30" height="30" rx="7" fill="${bar}"/><text x="${cw-25}" y="31" text-anchor="middle" font-size="17" font-weight="600" fill="#fff">${g}</text>`:''}</g>`});return{t:'KPI',s,h:2*ch+14}}
 if(k==='trend'){const e=embed(trendSvg(P,W),0,0,W);return{t:'รายได้เทียบค่าใช้จ่ายรายวัน (น้ำเงิน = รายได้, ทอง = ค่าใช้จ่าย)',s:e.s,h:e.h}}
 if(k==='cost'){const parts=costParts(K.o,P),e=embed(donut({parts,center:fmtP(M_.ratio(K.o),0),sub:'ของรายได้',P}),0,0,280);let s=e.s;parts.forEach((p,i)=>{s+=`<rect x="340" y="${20+i*44}" width="18" height="18" rx="4" fill="${p.c}"/><text x="370" y="${35+i*44}" font-size="18" fill="#0b1f3f">${esc(p.l)}</text><text x="${W-10}" y="${35+i*44}" text-anchor="end" font-size="18" fill="#0b1f3f">${fmtN(p.v)} บาท (${fmtP(p.v/rowCost(K.o)*100)})</text>`});return{t:'สัดส่วนค่าใช้จ่าย',s,h:290}}
 const T=(t,c,d)=>{const r=svgTable(c,d,W);return{t,s:r.s,h:r.h}};
 if(k==='zone')return T('ผลรายภาค',[colName('ภาค',o=>o.name),CN,...NUMCOLS.slice(0,5),PC],dim('zone').sort((a,b)=>pfOf(a)-pfOf(b)));
 if(k==='worst')return T('10 คันที่ขาดทุนสูงสุด',[colName('ทะเบียน',o=>o.name),...LOC,NUMCOLS[2],NUMCOLS[4]],dim('car').sort((a,b)=>pfOf(a)-pfOf(b)).slice(0,10));
 if(k==='cmp'){const{c,ms,rows:R}=cmpRows();return T('เทียบรายเดือนตามภาค: '+c.t,[colName('ภาค',o=>o.name),CN,...ms.map((m,i)=>({k:'m'+i,t:mLabel(m.M.m),v:o=>c.x(o.vals[i])}))],R)}
 if(k==='analysis'){const{k:mm,R}=analysisRows();return T('ผลการวิเคราะห์ เรียงจากแย่ไปดีตาม '+mm.t,[colName(S.adim==='car'?'ทะเบียน':S.adim==='dc'?'DC':'ภาค',o=>o.name),...(S.adim==='car'?LOC:[CN]),...[NUMCOLS[0],NUMCOLS[2],NUMCOLS[3],NUMCOLS[4]].filter(c=>c.k!==mm.k),...(['pf','ratio','util'].includes(mm.k)?[]:[{k:'x',t:mm.t,v:o=>mm.x(mm.f(o))}])],R.slice(0,20))}}

